function MiniProduct({name, desc, price, color}) { return <div className="mini-product"><div className={`food-thumb ${color}`}></div><div><b>{name}</b><small>{desc}</small><strong>{price}</strong></div></div> }

function Auth({ mode, onBack, onAuth, onSwitch }) {
  const [show, setShow] = useState(false); const [error, setError] = useState('');
  function submit(e) {
    e.preventDefault(); const fd = new FormData(e.currentTarget); const email = fd.get('email'); const password = fd.get('password'); const name = fd.get('name');
    const authError=onAuth({mode,name,email,password});
    if(authError)setError(authError);
  }
  return <div className="auth-page"><div className="auth-brand"><Logo light/><div><span className="eyebrow dark"><Sparkles/> Comece agora</span><h1>Seu cardápio digital,<br/><em>do seu jeito.</em></h1><p>Uma presença online bonita e prática para o seu negócio vender mais.</p></div><div className="auth-quote">“Em poucos minutos, tudo pronto para receber clientes.”</div></div>
    <main className="auth-main"><button className="back-button" onClick={onBack}><ArrowLeft/> Voltar</button><div className="auth-card"><span className="auth-mini-logo"><Utensils/></span><h2>{mode === 'login' ? 'Que bom ter você de volta' : 'Crie sua conta grátis'}</h2><p>{mode === 'login' ? 'Entre para gerenciar seu cardápio.' : 'Seu cardápio online em poucos minutos.'}</p>
      {mode === 'login' && <div className="demo-note"><b>Acesso de demonstração</b><span>{DEMO_EMAIL}</span><span>Senha: {DEMO_PASSWORD}</span></div>}
      <form onSubmit={submit} aria-label={mode === 'login' ? 'Entrar na conta' : 'Criar conta'}>
        {mode === 'signup' && <div className="field"><label htmlFor="name">Seu nome</label><input id="name" name="name" autoComplete="name" required placeholder="Como podemos chamar você?"/></div>}
        <div className="field"><label htmlFor="email">E-mail</label><input id="email" name="email" type="email" autoComplete="username" spellCheck="false" required defaultValue={mode === 'login' ? DEMO_EMAIL : ''} placeholder="voce@seunegocio.com.br" onInput={()=>setError('')}/></div>
        <div className="field"><div className="label-row"><label htmlFor="password">Senha</label>{mode === 'login' && <button type="button" className="text-button">Esqueci minha senha</button>}</div><div className="password-wrap"><input id="password" name="password" type={show ? 'text' : 'password'} autoComplete={mode === 'login' ? 'current-password' : 'new-password'} minLength="8" required defaultValue={mode === 'login' ? DEMO_PASSWORD : ''} aria-describedby="password-hint"/><button type="button" className="password-toggle" onClick={()=>setShow(!show)} aria-pressed={show} aria-label={show ? 'Ocultar senha' : 'Mostrar senha'}>{show ? <EyeOff/> : <Eye/>}</button></div>{mode === 'signup' && <small id="password-hint">Use pelo menos 8 caracteres.</small>}</div>
        {error && <p className="form-error" role="alert">{error}</p>}
        <button className="btn btn-primary btn-full btn-lg" type="submit">{mode === 'login' ? 'Entrar no painel' : 'Criar conta e continuar'} <ArrowRight/></button>
      </form><p className="auth-switch">{mode === 'login' ? 'Ainda não tem uma conta?' : 'Já tem uma conta?'} <button className="text-button strong" onClick={onSwitch}>{mode === 'login' ? 'Começar grátis' : 'Entrar'}</button></p></div></main>
  </div>
}

function Setup({data,onComplete,onLogout}){
  const [step,setStep]=useState(1);const [draft,setDraft]=useState({name:data.business.name,type:data.business.type||'Restaurante',description:data.business.description,slug:data.business.slug,address:data.business.address,hours:data.business.hours});const heading=useRef(null);
  useEffect(()=>{heading.current?.focus({preventScroll:true});scrollTo({top:0,behavior:'smooth'})},[step]);
  function nextBusiness(e){e.preventDefault();const fd=new FormData(e.currentTarget);const name=fd.get('businessName').trim();setDraft({...draft,name,type:fd.get('businessType'),slug:draft.slug||slugify(name)});setStep(2)}
  function nextDetails(e){e.preventDefault();const fd=new FormData(e.currentTarget);setDraft({...draft,description:fd.get('description').trim(),slug:slugify(fd.get('slug')),address:fd.get('address').trim(),hours:fd.get('hours').trim()});setStep(3)}
  function finish(){onComplete({...data,business:{...data.business,...draft,published:true},onboardingCompleted:true})}
  return <div className="setup-page"><header className="setup-header"><Logo/><button type="button" className="btn btn-ghost" onClick={onLogout}>Sair</button></header><main className="setup-main"><div className="setup-progress"><div><span>Configuração inicial</span><strong>Passo {step} de 3</strong></div><progress value={step} max="3">{step} de 3</progress><ol aria-label="Progresso da configuração"><li className={step>=1?'active':''} aria-current={step===1?'step':undefined}>Seu negócio</li><li className={step>=2?'active':''} aria-current={step===2?'step':undefined}>Informações</li><li className={step>=3?'active':''} aria-current={step===3?'step':undefined}>Primeiro cardápio</li></ol></div>
    {step===1&&<section className="setup-card"><span className="setup-icon"><Store/></span><span className="kicker">Vamos começar</span><h1 ref={heading} tabIndex="-1">Conte um pouco sobre seu negócio</h1><p>Usaremos essas informações para preparar seu cardápio inicial.</p><form onSubmit={nextBusiness} aria-labelledby="setup-business-title"><span id="setup-business-title" className="visually-hidden">Dados principais do negócio</span><div className="field"><label htmlFor="setup-business-name">Nome do estabelecimento</label><input id="setup-business-name" name="businessName" defaultValue={draft.name} autoComplete="organization" placeholder="Ex.: Bossa Café" required autoFocus enterKeyHint="next"/></div><fieldset className="business-type-options"><legend>Tipo de estabelecimento</legend>{['Restaurante','Cafeteria','Bar','Lanchonete'].map(type=><label key={type}><input type="radio" name="businessType" value={type} defaultChecked={draft.type===type}/><span>{type==='Cafeteria'?<Coffee/>:type==='Bar'?<CircleDollarSign/>:<Utensils/>}<b>{type}</b></span></label>)}</fieldset><button className="btn btn-primary btn-lg btn-full" type="submit">Continuar <ArrowRight/></button></form></section>}
    {step===2&&<section className="setup-card"><span className="setup-icon"><Pencil/></span><span className="kicker">Sua presença online</span><h1 ref={heading} tabIndex="-1">Complete as informações principais</h1><p>Você poderá alterar tudo depois no painel.</p><form onSubmit={nextDetails} aria-labelledby="setup-details-title"><span id="setup-details-title" className="visually-hidden">Informações públicas do negócio</span><div className="field"><label htmlFor="setup-description">Descrição curta</label><textarea id="setup-description" name="description" defaultValue={draft.description} placeholder="Conte em uma frase o que torna seu negócio especial." maxLength="160" required/></div><div className="field"><label htmlFor="setup-slug">Link exclusivo</label><div className="slug-field"><span>menuflow.com/</span><input id="setup-slug" name="slug" defaultValue={draft.slug||slugify(draft.name)} pattern="[a-z0-9-]+" spellCheck="false" required/></div></div><div className="setup-two-fields"><div className="field"><label htmlFor="setup-address">Endereço <small>(opcional)</small></label><input id="setup-address" name="address" defaultValue={draft.address} autoComplete="street-address"/></div><div className="field"><label htmlFor="setup-hours">Horário <small>(opcional)</small></label><input id="setup-hours" name="hours" defaultValue={draft.hours} placeholder="Ex.: Seg a Sáb · 8h às 19h"/></div></div><div className="setup-actions"><button className="btn btn-secondary" type="button" onClick={()=>setStep(1)}><ArrowLeft/> Voltar</button><button className="btn btn-primary" type="submit">Ver cardápio inicial <ArrowRight/></button></div></form></section>}
    {step===3&&<section className="setup-card setup-finish"><span className="setup-icon success"><BadgeCheck/></span><span className="kicker">Tudo pronto para editar</span><h1 ref={heading} tabIndex="-1">Seu cardápio já começa preenchido</h1><p>Adicionamos categorias e produtos com fotos para você entender o funcionamento. Edite ou exclua qualquer exemplo quando quiser.</p><div className="setup-product-grid">{data.products.slice(0,3).map(product=><article key={product.id}><img src={product.image} alt={product.name} width="220" height="165"/><div><b>{product.name}</b><small>{product.category}</small><strong>{money(product.price)}</strong></div></article>)}</div><div className="setup-tip"><Sparkles/><span><b>Nada está publicado sem seu controle.</b> Revise os exemplos no construtor e personalize seu cardápio antes de divulgar o link.</span></div><div className="setup-actions"><button className="btn btn-secondary" type="button" onClick={()=>setStep(2)}><ArrowLeft/> Voltar</button><button className="btn btn-primary btn-lg" type="button" onClick={finish}>Entrar no meu painel <ArrowRight/></button></div></section>}
  </main></div>
}

function Dashboard({ data, setData, onLogout, onPublic }) {
  const [section, setSection] = useState('overview'); const [dialogOpen, setDialogOpen] = useState(false); const [editing, setEditing] = useState(null); const [toast, setToast] = useState(''); const [mobileNav, setMobileNav] = useState(false);
  const publicUrl = `${location.origin}${location.pathname}?menu=${data.business.slug}`;
  const activeProducts = data.products.filter(p=>p.active).length;
  function notify(msg){ setToast(msg); setTimeout(()=>setToast(''), 2600); }
  function openProduct(product=null){ setEditing(product); setDialogOpen(true); }
  function saveProduct(e,image){ e.preventDefault(); const fd=new FormData(e.currentTarget); const item={ id: editing?.id || Date.now(), name:fd.get('name'), category:fd.get('category'), description:fd.get('description'), price:Number(String(fd.get('price')).replace(',','.')), tag:fd.get('tag'), active:editing?.active??true, image }; setData({...data,products:editing?data.products.map(p=>p.id===editing.id?item:p):[...data.products,item]}); setDialogOpen(false); notify(editing?'Produto atualizado.':'Produto adicionado.'); }
  function removeProduct(id){ setData({...data,products:data.products.filter(p=>p.id!==id)}); notify('Produto removido.'); }
  function toggleProduct(id){setData({...data,products:data.products.map(p=>p.id===id?{...p,active:!p.active}:p)});}
  function copyLink(){navigator.clipboard?.writeText(publicUrl); notify('Link copiado para a área de transferência.');}
  function downloadQr(){const canvas=document.querySelector('#qr-download canvas'); const a=document.createElement('a');a.download=`qrcode-${data.business.slug}.png`;a.href=canvas.toDataURL('image/png');a.click();}
  return <div className="dashboard-shell">
    <aside className={`sidebar ${mobileNav?'open':''}`}><div className="sidebar-top"><Logo light/><button className="icon-button close-nav" onClick={()=>setMobileNav(false)} aria-label="Fechar menu"><X/></button></div><div className="business-chip"><span>{data.business.name.slice(0,1)}</span><div><b>{data.business.name}</b><small>Plano Essencial</small></div></div>
      <nav aria-label="Painel"><SidebarLink icon={<LayoutDashboard/>} label="Visão geral" active={section==='overview'} onClick={()=>{setSection('overview');setMobileNav(false)}}/><SidebarLink icon={<Palette/>} label="Construtor visual" active={section==='builder'} onClick={()=>{setSection('builder');setMobileNav(false)}}/><SidebarLink icon={<Package/>} label="Produtos" badge={data.products.length} active={section==='products'} onClick={()=>{setSection('products');setMobileNav(false)}}/><SidebarLink icon={<QrCode/>} label="Link e QR Code" active={section==='share'} onClick={()=>{setSection('share');setMobileNav(false)}}/><SidebarLink icon={<Store/>} label="Meu negócio" active={section==='business'} onClick={()=>{setSection('business');setMobileNav(false)}}/></nav>
      <div className="sidebar-bottom"><button onClick={()=>onPublic()}><ExternalLink/> Ver cardápio</button><button onClick={onLogout}><LogOut/> Sair da conta</button><div className="user-chip"><span>{data.account.name.slice(0,1)}</span><div><b>{data.account.name}</b><small>{data.account.email}</small></div></div></div>
    </aside>
    <main className="dashboard-main"><header className="dash-header"><button className="icon-button mobile-menu" onClick={()=>setMobileNav(true)} aria-label="Abrir menu"><Menu/></button><div><h1>{section==='overview'?'Visão geral':section==='builder'?'Construtor visual':section==='products'?'Produtos':section==='share'?'Link e QR Code':'Meu negócio'}</h1><p>{section==='overview'?`Olá, ${data.account.name.split(' ')[0]}! Aqui está o resumo do seu cardápio.`:section==='builder'?'Edite e acompanhe o resultado em tempo real.':section==='products'?'Gerencie os itens disponíveis no seu cardápio.':section==='share'?'Divulgue seu cardápio com um endereço que não muda.':'Atualize as informações exibidas aos seus clientes.'}</p></div><button className="btn btn-secondary desktop-only" onClick={onPublic}><Eye/> Ver cardápio</button></header>
      <div className="dash-content">
      {section==='overview' && <Overview data={data} activeProducts={activeProducts} onSection={setSection} onPublic={onPublic}/>} 
      {section==='builder' && <MenuBuilder data={data} setData={setData} notify={notify}/>} 
      {section==='products' && <Products data={data} onAdd={()=>openProduct()} onEdit={openProduct} onRemove={removeProduct} onToggle={toggleProduct}/>} 
      {section==='share' && <Share data={data} publicUrl={publicUrl} copyLink={copyLink} downloadQr={downloadQr} onPublic={onPublic}/>} 
      {section==='business' && <Business data={data} setData={setData} notify={notify}/>} 
      </div>
    </main>
    {dialogOpen && <ProductDialog categories={data.categories} product={editing} onClose={()=>setDialogOpen(false)} onSubmit={saveProduct}/>}<div className={`toast ${toast?'show':''}`} role="status"><BadgeCheck/>{toast}</div>
  </div>;
}

function MenuBuilder({data,setData,notify}){
  const [panel,setPanel]=useState('visual'); const [device,setDevice]=useState('desktop'); const [selectedId,setSelectedId]=useState(data.products[0]?.id); const [newCategory,setNewCategory]=useState(''); const [deleteCategory,setDeleteCategory]=useState(null); const [logoError,setLogoError]=useState(''); const [productImageError,setProductImageError]=useState(''); const deleteDialog=useRef(null); const builderPanel=useRef(null); const productEditorHeading=useRef(null); const selected=data.products.find(p=>p.id===selectedId);
  const updateDesign=(key,value)=>setData({...data,design:{...data.design,[key]:value}});
  const updateBusiness=(key,value)=>setData({...data,business:{...data.business,[key]:value}});
  const updateProduct=(key,value)=>setData({...data,products:data.products.map(p=>p.id===selectedId?{...p,[key]:value}:p)});
  function moveCategory(index,direction){const next=[...data.categories];const target=index+direction;if(target<0||target>=next.length)return;[next[index],next[target]]=[next[target],next[index]];setData({...data,categories:next});notify(`${next[target]} movida para a posição ${target+1}.`)}
  function addCategory(e){e.preventDefault();const name=newCategory.trim();if(!name)return;if(data.categories.some(c=>c.toLowerCase()===name.toLowerCase())){notify('Já existe uma categoria com esse nome.');return}setData({...data,categories:[...data.categories,name]});setNewCategory('');notify(`${name} criada.`)}
  function renameCategory(oldName,newName){const name=newName.trim();if(!name||name===oldName)return;setData({...data,categories:data.categories.map(c=>c===oldName?name:c),products:data.products.map(p=>p.category===oldName?{...p,category:name}:p)});notify(`${oldName} renomeada para ${name}.`)}
  function askDeleteCategory(name){if(data.categories.length===1){notify('Mantenha pelo menos uma categoria.');return}setDeleteCategory(name);requestAnimationFrame(()=>deleteDialog.current?.showModal())}
  function confirmDeleteCategory(){if(!deleteCategory)return;const remaining=data.categories.filter(c=>c!==deleteCategory);const destination=remaining[0];const affected=data.products.filter(p=>p.category===deleteCategory).length;setData({...data,categories:remaining,products:data.products.map(p=>p.category===deleteCategory?{...p,category:destination}:p)});deleteDialog.current?.close();notify(affected?`${deleteCategory} excluída. ${affected} produto(s) movido(s) para ${destination}.`:`${deleteCategory} excluída.`);setDeleteCategory(null)}
  function uploadLogo(e){const file=e.target.files?.[0];if(!file)return;setLogoError('');if(!['image/png','image/jpeg','image/webp'].includes(file.type)){setLogoError('Use uma imagem PNG, JPG ou WebP.');e.target.value='';return}if(file.size>5*1024*1024){setLogoError('A imagem deve ter no máximo 5 MB.');e.target.value='';return}optimizeImage(file,result=>{updateBusiness('logo',result);notify('Logo atualizada.');},()=>setLogoError('Não foi possível ler esta imagem.'))}
  function openProductEditor(id){setSelectedId(id);setProductImageError('');setPanel('product');requestAnimationFrame(()=>{builderPanel.current?.scrollTo({top:0});productEditorHeading.current?.focus({preventScroll:true})})}
  function openPanel(nextPanel){setPanel(nextPanel);requestAnimationFrame(()=>builderPanel.current?.scrollTo({top:0}))}
  function uploadProductImage(e){const file=e.target.files?.[0];if(!file)return;setProductImageError('');if(!['image/png','image/jpeg','image/webp'].includes(file.type)){setProductImageError('Use uma imagem PNG, JPG ou WebP.');e.target.value='';return}if(file.size>5*1024*1024){setProductImageError('A imagem deve ter no máximo 5 MB.');e.target.value='';return}optimizeImage(file,result=>{updateProduct('image',result);notify('Imagem do produto atualizada.');},()=>setProductImageError('Não foi possível ler esta imagem.'))}
  const palettes=[['#6352d9','#1b2721','#34483d','#faf8f3'],['#c75532','#342019','#754433','#fff8ef'],['#15726b','#173533','#28706a','#f1faf7'],['#b18421','#20201d','#5d5430','#fbf7ea'],['#c24f72','#40222d','#7b4053','#fff5f7']];
  return <><div className="builder-shell">
    <aside className="builder-controls" aria-label="Controles do construtor">
      <div className="builder-tabs" role="tablist" aria-label="Configurações"><button role="tab" aria-selected={panel==='visual'} className={panel==='visual'?'active':''} onClick={()=>openPanel('visual')}><Palette/> Aparência</button><button role="tab" aria-selected={panel==='content'||panel==='product'} className={panel==='content'||panel==='product'?'active':''} onClick={()=>openPanel('content')}><Pencil/> Conteúdo</button><button role="tab" aria-selected={panel==='order'} className={panel==='order'?'active':''} onClick={()=>openPanel('order')}><GripVertical/> Ordem</button></div>
      <div className="builder-panel" ref={builderPanel}>
      {panel==='visual'&&<>
        <div className="control-group"><div className="control-heading"><div><b>Estilo do cardápio</b><small>Escolha uma combinação inicial.</small></div></div><div className="palette-grid">{palettes.map((p,i)=><button key={p[0]} className={data.design.accent===p[0]&&data.design.cover===p[1]?'selected':''} onClick={()=>setData({...data,design:{...data.design,accent:p[0],cover:p[1],coverEnd:p[2],surface:p[3]}})} aria-label={`Usar paleta ${i+1}`}>{p.map(c=><i key={c} style={{background:c}}/>)}<Check/></button>)}</div></div>
        <div className="control-group"><label htmlFor="accent-color">Cor de destaque</label><div className="color-control"><input id="accent-color" type="color" value={data.design.accent} onChange={e=>updateDesign('accent',e.target.value)}/><input value={data.design.accent} onChange={e=>updateDesign('accent',e.target.value)} pattern="#[0-9a-fA-F]{6}" aria-label="Valor hexadecimal da cor de destaque"/></div></div>
        <div className="control-group"><span className="control-label">Gradiente do banner</span><div className="banner-color-grid"><label htmlFor="banner-start"><span>Início</span><input id="banner-start" type="color" value={data.design.cover} onChange={e=>updateDesign('cover',e.target.value)}/></label><label htmlFor="banner-end"><span>Fim</span><input id="banner-end" type="color" value={data.design.coverEnd} onChange={e=>updateDesign('coverEnd',e.target.value)}/></label></div><small className="control-hint">Combine duas cores para personalizar o topo do cardápio.</small></div>
        <div className="control-group"><span className="control-label">Layout dos produtos</span><div className="segmented"><button className={data.design.layout==='cards'?'active':''} onClick={()=>updateDesign('layout','cards')}>Cards</button><button className={data.design.layout==='list'?'active':''} onClick={()=>updateDesign('layout','list')}>Lista</button></div><small className="control-hint">Cards destacam as imagens; lista prioriza uma leitura rápida.</small></div>
        <div className="control-group"><label htmlFor="corner-radius">Arredondamento <output>{data.design.radius}px</output></label><input id="corner-radius" type="range" min="0" max="28" value={data.design.radius} onChange={e=>updateDesign('radius',Number(e.target.value))}/></div>
        <div className="control-group checks"><label><input type="checkbox" checked={data.design.showDescriptions} onChange={e=>updateDesign('showDescriptions',e.target.checked)}/> Mostrar descrições</label><label><input type="checkbox" checked={data.design.showPrices} onChange={e=>updateDesign('showPrices',e.target.checked)}/> Mostrar valores</label><label><input type="checkbox" checked={data.design.showSearch} onChange={e=>updateDesign('showSearch',e.target.checked)}/> Mostrar busca</label></div>
      </>}
      {panel==='content'&&<>
        <div className="control-group logo-uploader"><span className="control-label">Logo do estabelecimento</span><div className="logo-upload-row"><span className="logo-upload-preview">{data.business.logo?<img src={data.business.logo} alt="Logo atual do estabelecimento" width="64" height="64"/>:<Coffee aria-hidden="true"/>}</span><div><label className="upload-button" htmlFor="builder-logo"><ImagePlus/> Enviar logo</label><input className="visually-hidden" id="builder-logo" type="file" accept="image/png,image/jpeg,image/webp" onChange={uploadLogo}/><small id="logo-help">PNG, JPG ou WebP · máximo 5 MB.</small>{data.business.logo&&<button className="remove-logo" type="button" onClick={()=>updateBusiness('logo','')}>Remover logo</button>}</div></div>{logoError&&<p className="upload-error" role="alert">{logoError}</p>}</div>
        <div className="control-group"><label htmlFor="builder-name">Nome do estabelecimento</label><input id="builder-name" value={data.business.name} onChange={e=>updateBusiness('name',e.target.value)}/></div>
        <div className="control-group"><label htmlFor="builder-description">Descrição</label><textarea id="builder-description" value={data.business.description} onChange={e=>updateBusiness('description',e.target.value)} maxLength="160"/></div>
        <p className="builder-help">Para editar um produto, clique no ícone de lápis que aparece sobre ele na prévia.</p>
      </>}
      {panel==='product'&&selected&&<div className="context-product-editor">
        <button type="button" className="builder-back" onClick={()=>openPanel('content')}><ArrowLeft/> Voltar ao conteúdo</button>
        <div className="context-editor-heading"><span className="kicker">Produto selecionado</span><h2 ref={productEditorHeading} tabIndex="-1">Editar produto</h2><p>As alterações aparecem imediatamente na prévia.</p></div>
        <div className="product-image-uploader compact"><div className="product-image-preview">{selected.image?<img src={selected.image} alt={`Prévia de ${selected.name}`} width="120" height="120"/>:<ImagePlus aria-hidden="true"/>}</div><div><label className="upload-button" htmlFor="builder-product-image"><ImagePlus/> {selected.image?'Trocar imagem':'Adicionar imagem'}</label><input className="visually-hidden" id="builder-product-image" type="file" accept="image/png,image/jpeg,image/webp" onChange={uploadProductImage}/><small>PNG, JPG ou WebP · máximo 5 MB.</small>{selected.image&&<button type="button" className="remove-logo" onClick={()=>updateProduct('image','')}>Remover imagem</button>}</div></div>
        {productImageError&&<p className="upload-error" role="alert">{productImageError}</p>}
        <div className="control-group"><label htmlFor="builder-product-name">Nome</label><input id="builder-product-name" value={selected.name} onChange={e=>updateProduct('name',e.target.value)}/></div>
        <div className="control-group"><label htmlFor="builder-product-desc">Descrição</label><textarea id="builder-product-desc" value={selected.description} maxLength="160" onChange={e=>updateProduct('description',e.target.value)}/></div>
        <div className="control-group"><label htmlFor="builder-product-price">Preço (R$)</label><input id="builder-product-price" type="number" inputMode="decimal" min="0" step="0.01" value={selected.price} onChange={e=>updateProduct('price',Number(e.target.value))}/></div>
        <div className="control-group"><label htmlFor="builder-product-category">Categoria</label><select id="builder-product-category" value={selected.category} onChange={e=>updateProduct('category',e.target.value)}>{data.categories.map(category=><option key={category}>{category}</option>)}</select></div>
        <div className="control-group"><label htmlFor="builder-product-tag">Destaque <small>(opcional)</small></label><input id="builder-product-tag" value={selected.tag||''} placeholder="Ex.: Mais pedido" onChange={e=>updateProduct('tag',e.target.value)}/></div>
        <div className="control-group checks"><label><input type="checkbox" checked={selected.active} onChange={e=>updateProduct('active',e.target.checked)}/> Produto visível no cardápio</label></div>
      </div>}
      {panel==='order'&&<><div className="control-heading"><div><b>Abas e categorias</b><small>Crie, renomeie, exclua ou altere a ordem.</small></div></div><form className="add-category" onSubmit={addCategory}><label className="visually-hidden" htmlFor="new-category">Nome da nova categoria</label><input id="new-category" value={newCategory} onChange={e=>setNewCategory(e.target.value)} placeholder="Ex.: Bebidas" maxLength="40" required/><button className="btn btn-primary" type="submit" aria-label="Criar categoria"><Plus/></button></form><div className="sortable-categories" role="list">{data.categories.map((cat,i)=><div role="listitem" key={cat}><GripVertical aria-hidden="true"/><input defaultValue={cat} key={cat} onBlur={e=>renameCategory(cat,e.target.value)} onKeyDown={e=>{if(e.key==='Enter'){e.preventDefault();e.currentTarget.blur()}}} aria-label={`Nome da categoria ${cat}`}/><button onClick={()=>moveCategory(i,-1)} disabled={i===0} aria-label={`Mover ${cat} para cima`}><MoveUp/></button><button onClick={()=>moveCategory(i,1)} disabled={i===data.categories.length-1} aria-label={`Mover ${cat} para baixo`}><MoveDown/></button><button className="delete-category" onClick={()=>askDeleteCategory(cat)} aria-label={`Excluir categoria ${cat}`}><Trash2/></button></div>)}</div><p className="builder-help">As abas do cardápio são geradas a partir das categorias. Pressione Enter ou saia do campo para salvar um novo nome.</p></>}
      </div>
    </aside>
    <section className="builder-stage" aria-label="Prévia do cardápio">
      <div className="builder-toolbar"><div><span className="save-indicator"><BadgeCheck/> Salvo automaticamente</span></div><div className="device-switch" aria-label="Tamanho da prévia"><button className={device==='desktop'?'active':''} onClick={()=>setDevice('desktop')} aria-label="Visualização para computador"><Monitor/></button><button className={device==='mobile'?'active':''} onClick={()=>setDevice('mobile')} aria-label="Visualização para celular"><Smartphone/></button></div></div>
      <div className={`preview-canvas ${device}`}><div className="preview-browser"><div className="browser-bar"><i/><i/><i/><span>menuflow.com/{data.business.slug}</span></div><div className="preview-viewport"><PublicMenu data={data} preview onEditProduct={openProductEditor}/></div></div></div>
    </section>
  </div><dialog ref={deleteDialog} className="confirm-dialog" aria-labelledby="delete-category-title" onClose={()=>setDeleteCategory(null)}><h2 id="delete-category-title">Excluir “{deleteCategory}”?</h2><p>{data.products.filter(p=>p.category===deleteCategory).length?`Os produtos desta categoria serão movidos para “${data.categories.find(c=>c!==deleteCategory)}”.`:'Esta categoria será removida do cardápio.'}</p><div className="confirm-actions"><button className="btn btn-secondary" type="button" autoFocus onClick={()=>deleteDialog.current?.close()}>Cancelar</button><button className="btn btn-danger" type="button" onClick={confirmDeleteCategory}>Excluir categoria</button></div></dialog></>
}

function SidebarLink({icon,label,badge,active,onClick}){return <button className={active?'active':''} onClick={onClick}>{icon}<span>{label}</span>{badge!==undefined&&<i>{badge}</i>}</button>}
function Overview({data,activeProducts,onSection,onPublic}){return <><div className="status-banner"><div><span className="live-dot"></span><div><b>Seu cardápio está publicado</b><small>Clientes já podem acessar pelo link ou QR Code.</small></div></div><button className="btn btn-light" onClick={onPublic}>Abrir cardápio <ExternalLink/></button></div><div className="metric-grid"><Metric icon={<Package/>} label="Produtos ativos" value={activeProducts} detail={`${data.products.length} cadastrados`} tone="purple"/><Metric icon={<QrCode/>} label="Acessos este mês" value="248" detail="↑ 18% vs. mês anterior" tone="orange"/><Metric icon={<BarChart3/>} label="Atualizações" value="12" detail="Nos últimos 30 dias" tone="green"/></div><div className="overview-grid"><section className="dash-card"><div className="card-heading"><div><h2>Ações rápidas</h2><p>Continue preparando seu cardápio.</p></div></div><div className="quick-actions"><button onClick={()=>onSection('products')}><span><Plus/></span><div><b>Adicionar produto</b><small>Inclua um novo item no cardápio</small></div><ChevronRight/></button><button onClick={()=>onSection('share')}><span><QrCode/></span><div><b>Baixar QR Code</b><small>Pronto para imprimir e usar</small></div><ChevronRight/></button><button onClick={()=>onSection('business')}><span><Settings/></span><div><b>Editar informações</b><small>Horários, contato e endereço</small></div><ChevronRight/></button></div></section><section className="dash-card preview-card"><div className="card-heading"><div><h2>Prévia do cardápio</h2><p>Como seus clientes estão vendo.</p></div><button className="text-button strong" onClick={onPublic}>Ver completo</button></div><div className="menu-preview"><span className="preview-avatar"><Coffee/></span><h3>{data.business.name}</h3><small>{data.business.description}</small>{data.products.filter(p=>p.active).slice(0,3).map(p=><div className="preview-row" key={p.id}><div><b>{p.name}</b><small>{p.description}</small></div><strong>{money(p.price)}</strong></div>)}</div></section></div></>}
function Metric({icon,label,value,detail,tone}){return <article className="metric"><span className={tone}>{icon}</span><div><small>{label}</small><strong>{value}</strong><em>{detail}</em></div></article>}
function Products({data,onAdd,onEdit,onRemove,onToggle}){const[query,setQuery]=useState('');const filtered=data.products.filter(p=>p.name.toLowerCase().includes(query.toLowerCase()));return <section className="dash-card products-card"><div className="product-toolbar"><label className="search-box"><Search/><span className="visually-hidden">Buscar produtos</span><input type="search" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar produto..."/></label><button className="btn btn-primary" onClick={onAdd}><Plus/> Novo produto</button></div><div className="product-list">{filtered.map(p=><article className="product-row" key={p.id}><div className="product-placeholder">{p.image?<img src={p.image} alt="" width="52" height="52" loading="lazy"/>:<Utensils/>}</div><div className="product-info"><div><h3>{p.name}</h3>{p.tag&&<span>{p.tag}</span>}</div><p>{p.description}</p><small>{p.category}</small></div><strong className="product-price">{money(p.price)}</strong><label className="switch"><input type="checkbox" checked={p.active} onChange={()=>onToggle(p.id)}/><span></span><i>{p.active?'Ativo':'Oculto'}</i></label><div className="row-actions"><button onClick={()=>onEdit(p)} aria-label={`Editar ${p.name}`}><Pencil/></button><button onClick={()=>onRemove(p.id)} aria-label={`Excluir ${p.name}`}><Trash2/></button></div></article>)}{filtered.length===0&&<div className="empty-state"><Search/><h3>Nenhum produto encontrado</h3><p>Tente outro termo ou adicione um novo produto.</p></div>}</div></section>}
function Share({data,publicUrl,copyLink,downloadQr,onPublic}){return <div className="share-grid"><section className="dash-card qr-card"><span className="kicker">QR Code permanente</span><h2>Imprima uma vez. Atualize sempre.</h2><p>Mesmo que produtos e preços mudem, este QR Code continuará levando ao seu cardápio.</p><div id="qr-download" className="qr-display"><QRCodeCanvas value={publicUrl} size={220} bgColor="#ffffff" fgColor="#18251f" level="H" includeMargin/></div><button className="btn btn-primary btn-full" onClick={downloadQr}><Download/> Baixar QR Code em PNG</button></section><section className="dash-card link-card"><span className="link-icon"><Link2/></span><h2>Link do seu cardápio</h2><p>Compartilhe nas redes sociais, no WhatsApp e no perfil do Google.</p><label htmlFor="public-link">Endereço público</label><div className="copy-field"><input id="public-link" value={publicUrl} readOnly/><button onClick={copyLink}><Clipboard/> Copiar</button></div><div className="link-tip"><Globe2/><p><b>Seu identificador é fixo</b><span>O endereço <strong>/{data.business.slug}</strong> continua o mesmo após qualquer atualização.</span></p></div><button className="btn btn-secondary btn-full" onClick={onPublic}>Abrir cardápio público <ExternalLink/></button></section></div>}
function Business({data,setData,notify}){function submit(e){e.preventDefault();const fd=new FormData(e.currentTarget);const business={...data.business,name:fd.get('businessName'),slug:slugify(fd.get('slug')),type:fd.get('type'),description:fd.get('description'),address:fd.get('address'),whatsapp:fd.get('whatsapp'),hours:fd.get('hours')};setData({...data,business});notify('Informações salvas com sucesso.')}return <section className="dash-card business-form"><form onSubmit={submit}><div className="form-section"><h2>Identidade do negócio</h2><p>Essas informações aparecem no topo do seu cardápio.</p><div className="form-grid"><div className="field"><label htmlFor="businessName">Nome do estabelecimento</label><input id="businessName" name="businessName" defaultValue={data.business.name} required/></div><div className="field"><label htmlFor="type">Tipo de negócio</label><select id="type" name="type" defaultValue={data.business.type}><option>Restaurante</option><option>Bar</option><option>Cafeteria</option><option>Lanchonete</option><option>Outro</option></select></div><div className="field full"><label htmlFor="description">Descrição</label><textarea id="description" name="description" defaultValue={data.business.description} maxLength="160"/></div></div></div><div className="form-section"><h2>Link exclusivo</h2><p>Escolha um identificador curto e fácil de lembrar.</p><div className="slug-field"><span>menuflow.com/</span><input name="slug" defaultValue={data.business.slug} required pattern="[a-z0-9-]+"/></div></div><div className="form-section"><h2>Contato e funcionamento</h2><div className="form-grid"><div className="field"><label htmlFor="whatsapp">WhatsApp</label><input id="whatsapp" name="whatsapp" defaultValue={data.business.whatsapp} autoComplete="tel"/></div><div className="field"><label htmlFor="hours">Horário</label><input id="hours" name="hours" defaultValue={data.business.hours}/></div><div className="field full"><label htmlFor="address">Endereço</label><input id="address" name="address" defaultValue={data.business.address} autoComplete="street-address"/></div></div></div><div className="form-footer"><button className="btn btn-primary btn-lg" type="submit">Salvar alterações</button></div></form></section>}
function ProductDialog({categories,product,onClose,onSubmit}){const[image,setImage]=useState(product?.image||'');const[imageError,setImageError]=useState('');function chooseImage(e){const file=e.target.files?.[0];if(!file)return;setImageError('');if(!['image/png','image/jpeg','image/webp'].includes(file.type)){setImageError('Use uma imagem PNG, JPG ou WebP.');e.target.value='';return}if(file.size>5*1024*1024){setImageError('A imagem deve ter no máximo 5 MB.');e.target.value='';return}optimizeImage(file,setImage,()=>setImageError('Não foi possível ler esta imagem.'))}return <div className="dialog-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><div className="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div className="dialog-header"><div><span className="kicker">Cardápio</span><h2 id="dialog-title">{product?'Editar produto':'Novo produto'}</h2></div><button className="icon-button" onClick={onClose} aria-label="Fechar"><X/></button></div><form onSubmit={e=>onSubmit(e,image)}><div className="product-image-uploader"><div className="product-image-preview">{image?<img src={image} alt="Prévia da imagem do produto" width="120" height="120"/>:<ImagePlus aria-hidden="true"/>}</div><div><label className="upload-button" htmlFor="product-image"><ImagePlus/> {image?'Trocar imagem':'Adicionar imagem'}</label><input className="visually-hidden" id="product-image" type="file" accept="image/png,image/jpeg,image/webp" onChange={chooseImage}/><small>PNG, JPG ou WebP · máximo 5 MB.</small>{image&&<button type="button" className="remove-logo" onClick={()=>setImage('')}>Remover imagem</button>}</div></div>{imageError&&<p className="upload-error" role="alert">{imageError}</p>}<div className="field"><label htmlFor="product-name">Nome do produto</label><input id="product-name" name="name" defaultValue={product?.name} required autoFocus/></div><div className="form-grid"><div className="field"><label htmlFor="product-category">Categoria</label><select id="product-category" name="category" defaultValue={product?.category||categories[0]}>{categories.map(c=><option key={c}>{c}</option>)}</select></div><div className="field"><label htmlFor="product-price">Preço (R$)</label><input id="product-price" name="price" inputMode="decimal" defaultValue={product?.price?.toFixed(2).replace('.',',')} pattern="[0-9]+([,.][0-9]{1,2})?" required/></div></div><div className="field"><label htmlFor="product-description">Descrição</label><textarea id="product-description" name="description" defaultValue={product?.description} maxLength="160" required/></div><div className="field"><label htmlFor="product-tag">Destaque <small>(opcional)</small></label><input id="product-tag" name="tag" defaultValue={product?.tag} placeholder="Ex.: Mais pedido"/></div><div className="dialog-actions"><button type="button" className="btn btn-secondary" onClick={onClose}>Cancelar</button><button type="submit" className="btn btn-primary">{product?'Salvar alterações':'Adicionar produto'}</button></div></form></div></div>}

function PublicMenu({data,onBack,preview=false,onEditProduct}){const[category,setCategory]=useState('Todos');const[query,setQuery]=useState('');const design={...seed.design,...data.design};useEffect(()=>{if(category!=='Todos'&&!data.categories.includes(category))setCategory('Todos')},[category,data.categories]);const products=data.products.filter(p=>p.active&&(category==='Todos'||p.category===category)&&p.name.toLowerCase().includes(query.toLowerCase()));const style={'--menu-accent':design.accent,'--menu-cover':design.cover,'--menu-cover-end':design.coverEnd,'--menu-surface':design.surface,'--menu-radius':`${design.radius}px`};return <div className={`public-menu menu-layout-${design.layout} ${preview?'is-preview':''}`} style={style}><header className="public-cover"><div className="public-top"><Logo light/>{onBack&&<button className="btn btn-light" onClick={onBack}><ArrowLeft/> Voltar ao painel</button>}</div><div className="public-identity"><span>{data.business.logo?<img src={data.business.logo} alt={`Logo de ${data.business.name}`} width="84" height="84"/>:<Coffee aria-hidden="true"/>}</span><div><div className="open-pill"><i></i> Aberto agora</div><h1>{data.business.name}</h1><p>{data.business.description}</p><small>{data.business.address} · {data.business.hours}</small></div></div></header><main className="public-content"><div className="public-tools">{design.showSearch&&<label className="public-search"><Search/><span className="visually-hidden">Buscar no cardápio</span><input type="search" placeholder="O que você procura?" value={query} onChange={e=>setQuery(e.target.value)}/></label>}<div className="category-tabs"><button className={category==='Todos'?'active':''} onClick={()=>setCategory('Todos')}>Todos</button>{data.categories.map(c=><button key={c} className={category===c?'active':''} onClick={()=>setCategory(c)}>{c}</button>)}</div></div>{data.categories.map(cat=>{const items=products.filter(p=>p.category===cat);if(!items.length)return null;return <section key={cat} className="public-category"><div className="category-title"><span></span><h2>{cat}</h2><small>{items.length} {items.length===1?'item':'itens'}</small></div><div className="public-products">{items.map((p,i)=><article key={p.id}>{onEditProduct&&<button type="button" className="visual-edit-button" onClick={()=>onEditProduct(p.id)} aria-label={`Editar ${p.name}`}><Pencil aria-hidden="true"/><span>Editar</span></button>}<div className={`public-food food-${(i%4)+1}`}>{p.image?<img src={p.image} alt={p.name} width="360" height="270" loading="lazy"/>:<Utensils aria-hidden="true"/>}</div><div><div className="product-title-line"><h3>{p.name}</h3>{p.tag&&<span>{p.tag}</span>}</div>{design.showDescriptions&&<p>{p.description}</p>}{design.showPrices&&<strong>{money(p.price)}</strong>}</div></article>)}</div></section>})}{products.length===0&&<div className="empty-state"><Search/><h3>Nada por aqui</h3><p>Tente buscar outro nome ou categoria.</p></div>}</main><footer className="public-footer"><Logo/><p>Cardápio digital por MenuFlow</p></footer></div>}

function App(){
  const initial=useMemo(()=>{const accounts=loadAccounts();const session=(localStorage.getItem(SESSION_KEY)||'').toLowerCase();const active=accounts[session];const params=new URLSearchParams(location.search);const publicSlug=params.get('menu');const publicWorkspace=publicSlug?Object.values(accounts).map(entry=>entry.workspace).find(workspace=>workspace.business.slug===publicSlug):null;return{accounts,session:active?session:'',data:active?normalizeWorkspace(active.workspace):normalizeWorkspace(accounts[DEMO_EMAIL].workspace),view:publicSlug?'public':active?(active.workspace.onboardingCompleted?'dashboard':'setup'):'landing',publicWorkspace}} ,[]);
  const[accounts,setAccounts]=useState(initial.accounts);const[currentEmail,setCurrentEmail]=useState(initial.session);const[data,setDataState]=useState(initial.data);const[view,setView]=useState(initial.view);const[publicWorkspace,setPublicWorkspace]=useState(initial.publicWorkspace);
  function persistAccounts(next){setAccounts(next);localStorage.setItem(ACCOUNTS_KEY,JSON.stringify(next))}
  function setData(next){setDataState(next);if(!currentEmail)return;persistAccounts({...accounts,[currentEmail]:{...accounts[currentEmail],workspace:next}})}
  function auth({mode,name,email,password}){const normalized=email.trim().toLowerCase();if(mode==='signup'){if(accounts[normalized])return'Já existe uma conta com este e-mail. Entre com sua senha.';const account={name:name.trim(),email:normalized,password};const workspace=createNewWorkspace(account);const next={...accounts,[normalized]:{password,workspace}};persistAccounts(next);setCurrentEmail(normalized);setDataState(workspace);localStorage.setItem(SESSION_KEY,normalized);setView('setup');return''}const entry=accounts[normalized];if(!entry||entry.password!==password)return'E-mail ou senha incorretos. Confira os dados e tente novamente.';const workspace=normalizeWorkspace(entry.workspace);setCurrentEmail(normalized);setDataState(workspace);localStorage.setItem(SESSION_KEY,normalized);setView(workspace.onboardingCompleted?'dashboard':'setup');return''}
  function finishSetup(next){let slug=next.business.slug||slugify(next.business.name);const used=new Set(Object.entries(accounts).filter(([email])=>email!==currentEmail).map(([,entry])=>entry.workspace.business.slug));let suffix=2;const base=slug;while(used.has(slug))slug=`${base}-${suffix++}`;const completed={...next,business:{...next.business,slug},onboardingCompleted:true};setData(completed);setView('dashboard')}
  function logout(){localStorage.removeItem(SESSION_KEY);setCurrentEmail('');setDataState(normalizeWorkspace(accounts[DEMO_EMAIL].workspace));setView('landing')}
  function openPublic(){setPublicWorkspace(data);setView('public')}
  useEffect(()=>{document.title=view==='dashboard'?'Painel | MenuFlow':view==='setup'?'Configure seu cardápio | MenuFlow':view==='public'?`${(publicWorkspace||data).business.name} | Cardápio`:'MenuFlow — seu cardápio, sempre atualizado'},[view,data,publicWorkspace]);
  if(view==='landing')return <Landing onStart={()=>setView('signup')} onLogin={()=>setView('login')} onPreview={()=>{setPublicWorkspace(normalizeWorkspace(accounts[DEMO_EMAIL].workspace));setView('public')}}/>;
  if(view==='login'||view==='signup')return <Auth mode={view} onBack={()=>setView('landing')} onAuth={auth} onSwitch={()=>setView(view==='login'?'signup':'login')}/>;
  if(view==='setup')return <Setup data={data} onComplete={finishSetup} onLogout={logout}/>;
  if(view==='public')return <PublicMenu data={publicWorkspace||data} onBack={()=>setView(currentEmail?'dashboard':'landing')}/>;
  return <Dashboard data={data} setData={setData} onLogout={logout} onPublic={openPublic}/>;
}

createRoot(document.getElementById('root')).render(<App/>);
